// --- Main Application Component ---
function CashFlowForecasterPrototype() {
  const [currentScreen, setCurrentScreen] = useState('integration'); // 'integration' | 'forecast'
  const [integrationStatus, setIntegrationStatus] = useState('idle'); // 'idle' | 'connecting' | 'connected'
  const [forecastPeriod, setForecastPeriod] = useState('90D'); // '30D' | '60D' | '90D'
  const [activeNav, setActiveNav] = useState('Forecast');

  const handleConnect = () => {
    setIntegrationStatus('connecting');
    setTimeout(() => {
      setIntegrationStatus('connected');
      setTimeout(() => {
        setCurrentScreen('forecast');
      }, 1000);
    }, 2000);
  };

  const integrations = [
    { name: 'Xero', icon: <XeroIcon />, description: 'Recommended for most businesses.' },
    { name: 'MYOB', icon: <MYOBIcon />, description: 'Popular in Australia & NZ.' },
    { name: 'QuickBooks', icon: <QuickBooksIcon />, description: 'Great for small businesses.' },
  ];

  const Header = () => (
    <header className="bg-white shadow-sm">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-4 flex justify-between items-center">
        <div className="flex items-center gap-2">
           <svg className="h-8 w-auto text-indigo-600" viewBox="0 0 24 24" fill="currentColor" xmlns="http://www.w3.org/2000/svg"><path d="M12 2L2 7l10 5 10-5-10-5zM2 17l10 5 10-5-10-5-10 5z"/></svg>
          <h1 className="text-xl font-bold text-slate-800">CashFlow AI</h1>
        </div>
        <nav className="hidden md:flex items-center space-x-2 bg-slate-100 p-1 rounded-lg">
          {['Dashboard', 'Forecast', 'Scenarios', 'Alerts'].map(item => (
            <button key={item} onClick={() => setActiveNav(item)} className={`px-3 py-1.5 text-sm font-medium rounded-md transition-colors ${activeNav === item ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-600 hover:bg-slate-200'}`}>
              {item}
            </button>
          ))}
        </nav>
        <div className="flex items-center gap-4">
          <p className="text-sm text-slate-600"><span className="font-medium text-slate-800">Sarah Chen</span></p>
          <img className="h-9 w-9 rounded-full object-cover" src="https://i.pravatar.cc/150?u=sarahchen" alt="Sarah Chen" />
        </div>
      </div>
    </header>
  );

  const IntegrationScreen = () => (
    <div className="max-w-3xl mx-auto text-center py-12">
      <h2 className="text-3xl font-bold text-slate-800">Connect your financial accounts</h2>
      <p className="mt-4 text-lg text-slate-600">Let's get started by connecting your accounting software. This allows us to securely analyze your data and generate your cash flow forecast.</p>
      <div className="mt-10 grid grid-cols-1 md:grid-cols-3 gap-6">
        {integrations.map((integration, index) => (
          <div key={integration.name} className={`bg-white border rounded-lg p-6 flex flex-col items-center text-center shadow-sm ${index === 0 ? 'border-indigo-500 ring-2 ring-indigo-200' : 'border-slate-200'}`}>
            {integration.icon}
            <h3 className="mt-4 text-lg font-semibold text-slate-800">{integration.name}</h3>
            <p className="mt-1 text-sm text-slate-500 flex-grow">{integration.description}</p>
            <button 
              onClick={index === 0 ? handleConnect : null} 
              disabled={index !== 0 || integrationStatus === 'connecting'}
              className={`w-full mt-6 px-4 py-2 text-sm font-semibold rounded-md transition-all flex items-center justify-center ${index === 0 ? 'bg-indigo-600 text-white hover:bg-indigo-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500' : 'bg-slate-200 text-slate-500 cursor-not-allowed'}`}>
              {integrationStatus === 'connecting' && index === 0 ? <><SpinnerIcon /> Connecting...</> : 'Connect'}
            </button>
          </div>
        ))}
      </div>
      {integrationStatus === 'connected' && (
        <div className="mt-8 flex items-center justify-center gap-2 text-green-600">
           <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
           <p className="font-semibold">Connection successful! Generating your forecast...</p>
        </div>
      )}
    </div>
  );

  const ForecastChart = () => {
    const dataPoints = [60, 65, 75, 70, 80, 90, 85, 95, 110, 105, 120, 130];
    const maxVal = Math.max(...dataPoints);
    const points = dataPoints.map((p, i) => `${(i / (dataPoints.length - 1)) * 100},${100 - (p / maxVal) * 80}`).join(' ');
    const areaPoints = `0,100 ${points} 100,100`;

    return (
      <div className="h-80 bg-white p-4 rounded-lg border border-slate-200 shadow-sm">
        <svg className="w-full h-full" viewBox="0 0 100 100" preserveAspectRatio="none">
          <defs>
            <linearGradient id="confidenceGradient" x1="0" y1="0" x2="0" y2="1">
              <stop offset="0%" stopColor="#818cf8" stopOpacity="0.2" />
              <stop offset="100%" stopColor="#818cf8" stopOpacity="0" />
            </linearGradient>
          </defs>
          <polyline fill="url(#confidenceGradient)" points={areaPoints} />
          <polyline fill="none" stroke="#4f46e5" strokeWidth="1" points={points} />
        </svg>
      </div>
    );
  };

  const ForecastScreen = () => (
    <div>
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-slate-800">90-Day Cash Flow Forecast</h2>
        <div className="flex items-center space-x-1 bg-slate-200 p-1 rounded-lg">
          {['30D', '60D', '90D'].map(period => (
            <button key={period} onClick={() => setForecastPeriod(period)} className={`px-3 py-1 text-sm font-medium rounded-md transition-colors ${forecastPeriod === period ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-600 hover:bg-slate-300'}`}>
              {period}
            </button>
          ))}
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 mb-6">
          <div className="bg-white border border-slate-200 rounded-lg p-5 shadow-sm">
              <h3 className="text-sm font-medium text-slate-500">Projected 90-Day Balance</h3>
              <p className="text-3xl font-bold text-slate-800 mt-2">$458,210</p>
              <p className="text-sm text-green-600 flex items-center mt-1">+12.5% from last period</p>
          </div>
          <div className="bg-white border border-amber-400 rounded-lg p-5 shadow-sm ring-2 ring-amber-100">
              <h3 className="text-sm font-medium text-amber-600">Potential Shortfall Alert</h3>
              <p className="text-3xl font-bold text-slate-800 mt-2">Oct 24, 2024</p>
              <p className="text-sm text-slate-500 mt-1">Projected dip below $50k threshold</p>
          </div>
          <div className="bg-white border border-slate-200 rounded-lg p-5 shadow-sm">
              <h3 className="text-sm font-medium text-slate-500">Credit Line Recommendation</h3>
              <p className="text-3xl font-bold text-slate-800 mt-2">Increase to $150k</p>
              <a href="#" className="text-sm text-indigo-600 hover:underline font-medium mt-1 inline-block">Review options &rarr;</a>
          </div>
      </div>

      <ForecastChart />

    </div>
  );

  return (
    <div className="min-h-screen bg-slate-50 font-sans">
      <Header />
      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {currentScreen === 'integration' ? <IntegrationScreen /> : <ForecastScreen />}
      </main>
    </div>
  );
}

export default CashFlowForecasterPrototype;

